-- Background job queue (docs/specs/mysql-migration.md §7.2), replacing pg-boss. Read and written only by
-- src/server/jobs/queue.ts. id is generated by the application so enqueue needs no read-back.

CREATE TABLE job (
  id CHAR(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL PRIMARY KEY,
  name VARCHAR(64) NOT NULL,
  data JSON NOT NULL,
  state VARCHAR(16) NOT NULL DEFAULT 'created'
    CHECK (state IN ('created', 'active', 'completed', 'failed', 'deadletter')),
  singleton_key VARCHAR(255),
  -- The 'short' policy as a unique key: at most one queued job per (name, singleton_key); an active job does not
  -- block a new one. NULL (not queued, or no key) never collides.
  queued_singleton VARCHAR(330) AS (IF(state = 'created' AND singleton_key IS NOT NULL,
                                       CONCAT(name, ':', singleton_key), NULL)) STORED,
  retry_count INT NOT NULL DEFAULT 0,
  retry_limit INT NOT NULL,
  retry_delay_s INT NOT NULL,
  start_after DATETIME(6) NOT NULL,
  -- Visibility timeout of an active job: past it the worker is presumed dead and the job is queued again.
  locked_until DATETIME(6),
  -- Set each time a worker claims the job. finish and retry match it, so a handler that outlived its visibility
  -- timeout cannot record an outcome over a later activation of the same job.
  claim_token CHAR(36) CHARACTER SET ascii COLLATE ascii_general_ci,
  output JSON,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  -- Set when the job reaches completed, failed or deadletter; retention deletes completed jobs by it.
  finished_at DATETIME(6),
  UNIQUE KEY job_queued_singleton (queued_singleton),
  KEY job_fetch (name, state, start_after)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_bin;

-- statement-break

GRANT SELECT, INSERT, UPDATE, DELETE ON job TO ${APP_DB_USER}
